package pgdriver

import (
	_http "net/http"

	_codes "google.golang.org/grpc/codes"
	lmterrors "last-mile-task/internal/errors"
)

// TODO(LASTMILE-062): the real store returns lmterrors.NewNotFoundError,
// generated by errgen into internal/errors. The skeleton's internal/errors
// exposes only the generic New constructor, so the same error (code
// lmt_not_found, codes.NotFound, HTTP 404) is built inline here. Replace with
// lmterrors.NewNotFoundError once the errgen output lands.
func notFoundError(details string) error {
	return lmterrors.New(
		"Not found.",
		"lmt_not_found",
		int32(_codes.NotFound),
		_http.StatusNotFound,
	).WithDetails(details)
}
